<template>
 <section class="safety-workspace">
  <header v-if="!recordOnly" class="workspace-heading"><div><p class="eyebrow">Clinical forms · Private records</p><h2>Clinical forms</h2><span v-if="catalog?.branding?.name" class="workspace-agency">{{ catalog.branding.name }}</span><p>Choose a document to start, or return to a saved record below.</p></div><span class="workspace-brand"><img src="/auricwell/mark.svg" alt="" />AuricWell EHR</span></header>
  <section v-if="!recordOnly" class="template-picker" aria-label="Start a new clinical document" :aria-busy="loading">
   <div class="picker-heading"><h3>Start a new document</h3><span>Choose a form to fill out</span></div>
   <div class="form-types">
    <button v-for="type in formTypes" :key="type.key" type="button" class="template-card"
      :class="{'template-card--active':documentKey===type.key&&(editing||record)}"
      :disabled="busy||loading" :aria-label="`Start new ${type.title}`" @click="startType(type.key)">
     <span class="document-preview" aria-hidden="true">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h5"/></svg>
      <span class="preview-rule preview-rule--heading"></span><span class="preview-rule"></span><span class="preview-rule"></span>
      <span class="preview-field"></span><span class="preview-field"></span>
      <span class="preview-plus">+</span>
     </span>
     <span class="template-copy"><strong>{{ type.title }}</strong><span class="template-description">{{ formDescriptions[type.key]||'Create and complete a private clinical document.' }}</span></span>
     <span class="template-action"><span class="new-document-dot" :class="{'new-document-dot--pulse':!editing&&!record}" aria-hidden="true"></span>Start new<span class="template-arrow" aria-hidden="true">→</span></span>
    </button>
   </div>
  </section>
  <router-link v-if="['safety-plan','cssrs-screener'].includes(documentKey)&&['itsco','nlu','tisi','isi'].includes(catalog?.branding?.slug)" :to="crisisPath">Crisis &amp; Emergency Response Guide · Safety planning →</router-link>
  <p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="loading">Loading clinical documents…</p>
  <div v-if="!loading && catalog" class="plan-layout" :class="{'record-only':recordOnly}">
   <aside v-if="!recordOnly" aria-label="Saved clinical forms"><h3>{{ clientId?'This client’s documents':'My documents and unlinked drafts' }}</h3><input v-model="savedSearch" type="search" aria-label="Search saved clinical documents" placeholder="Search saved documents…" /><p v-if="!filteredPlans.length">No saved documents match this form.</p><button v-for="p in filteredPlans" :key="p.id" type="button" :disabled="busy" @click="open(p.id)"><strong>{{ p.documentName||p.name||'Clinical form' }} · {{ p.title||'Safety plan' }}</strong><span v-if="!p.clientId" class="needs-client-link">Needs client link</span><span>{{ p.clientId?'Linked to a client':'Unlinked · private' }} · v{{ p.version }}<template v-if="p.documentKey==='cssrs-screener'"> · {{ p.screenStatus==='completed'?'Completed':'Draft' }}</template></span></button></aside>
   <div class="plan-content">
    <p v-if="!record&&!editing">Start a new form, or open a saved record. Without a client record, choose a private unlinked draft; return to it through Library → My files → Private clinical documents.</p>
    <form v-if="editing" @submit.prevent="save">
     <h3 ref="formHeading" class="active-form-heading" tabindex="-1">{{ record?'Edit':'New' }} {{ (record?.template||catalog.template).title.toLowerCase() }}</h3>
     <div v-if="!record&&!clientId" class="plan-linkage"><h3>Save in a client’s medical record</h3><NoteAidClientPicker v-if="!allowUnlinked" v-model="selectedClientId" :agency-id="agencyId" :search-all-tenants="false" @select="selectClient" /><label class="check"><input v-model="allowUnlinked" type="checkbox" @change="selectedClientId=null" />The client record is not available yet. Start a private unlinked draft.</label><label v-if="allowUnlinked">Reason for starting without a client record<textarea v-model="overrideReason" maxlength="2000" required /></label></div>
     <p v-if="record" class="notice">Saving creates a new version. Existing signatures stay with the version they signed. Share the revised version again when ready.</p>
     <SafetyPlanDocument :model-value="form" :template="record?.template||catalog.template" :branding="record?.branding||catalog.branding" editable @update:model-value="form=$event;dirty=true" />
     <div class="actions"><button :disabled="busy||(!record&&!clientId&&!selectedClientId&&!allowUnlinked)">{{ busy?'Saving…':form.screenStatus==='completed'?'Save completed screening':'Save draft' }}</button><button type="button" :disabled="busy" @click="cancelEdit">Cancel</button><span v-if="dirty">Unsaved changes</span></div>
    </form>
    <template v-else-if="record">
     <div class="actions"><button type="button" :disabled="busy||!!record.revocation" @click="edit">Edit as a new version</button><button v-if="record.clientId&&record.version===record.currentVersion&&!record.revocation" type="button" @click="focusSharing">Share to client portal</button><label>Saved version<select :value="record.version" :disabled="busy" @change="open(record.id,Number($event.target.value))"><option v-for="v in record.history" :key="v.version" :value="v.version">Version {{ v.version }} · {{ date(v.created_at) }}</option></select></label><button type="button" :disabled="busy" @click="open(record.id)">Refresh current version</button></div>
     <p v-if="record.version!==record.currentVersion" class="notice">You are viewing an earlier version. Open the current version to edit, share, or sign.</p>
     <p v-else-if="!record.clientId" class="notice"><strong>Needs client link.</strong> This saved form is private and is not yet in a client’s medical record. Attach it to the correct client when their record is available.</p>
     <p v-if="record.revocation" role="status">Authorization revoked on {{ date(record.revocation.recordedAt) }}. Prior signed versions are retained.</p>
     <p v-if="record.reviewStatus" class="notice">Form review: {{ record.reviewStatus==='reviewed'?'Reviewed by staff':'Awaiting staff review' }}. Submitted answers do not automatically overwrite the chart.</p>
      <details v-if="!record.clientId&&record.version===record.currentVersion&&!record.revocation" class="plan-linkage"><summary>Attach to a client’s medical record</summary><p>Choose the assigned client and confirm their identity. The document and its version history will be kept in their medical record.</p><NoteAidClientPicker v-model="linkClientId" :agency-id="record.agencyId" :search-all-tenants="false" /><label class="check"><input v-model="confirmIdentity" type="checkbox" />I verified this is the same individual. The organization and client link will be retained.</label><button type="button" :disabled="busy||!linkClientId||!confirmIdentity" @click="link">Attach to client record</button></details>
     <p v-if="record.clientId" class="notice">Saved in the client’s medical record. Authorized staff can open it from the client’s file.</p>
     <ClinicalDocumentCopy :document-element="()=>readDocument?.$el" :attendance="record.template.key==='attendance-verification'" />
     <SafetyPlanDocument ref="readDocument" :model-value="record.data" :template="record.template" :branding="record.branding" :version="record.version" :signers="record.signers" />
     <template v-if="record.version===record.currentVersion&&!record.revocation">

      <div class="actions"><button v-if="record.template.key==='release-of-information'" type="button" @click="revokeAuthorization">Record authorization revocation</button><button v-if="record.reviewStatus==='pending'" type="button" @click="reviewUpdate">Mark reviewed</button></div>
      <section ref="sharingSection" class="signers" tabindex="-1"><h3>Sign together or share to the portal</h3><p>Share a saved document for review and signature, or ask the client to complete an eligible form. Portal access follows the client’s current disclosure permissions. Email and enabled text notifications are grouped so adding documents does not send a separate alert for each one.</p>
       <div v-for="s in record.signers" :key="s.id" class="signer-row"><span>{{ s.name }} · {{ s.kind==='clinician'?'Staff':s.kind }} · {{ s.signedAt?'Signed':s.revokedAt?'Withdrawn':s.copyOnly?'Shared copy':s.sharedAt?'Available in portal':'Ready to sign together' }}</span><button v-if="!s.signedAt&&!s.revokedAt&&!s.copyOnly" type="button" :disabled="busy" @click="signing=s">{{ s.kind==='clinician'?'Sign as staff':'Sign together' }}</button><button v-if="!s.revokedAt" type="button" :disabled="busy" @click="revoke(s)">{{ s.sharedAt?'Withdraw portal access':'Withdraw request' }}</button></div>
       <form v-if="!signing" class="signer-setup" @submit.prevent="addSigner"><label>Signer<select aria-label="Signer" v-model="signerKind"><option value="client">Client</option><option value="guardian">Parent / guardian</option><option value="clinician">Me · staff signer</option></select></label><label v-if="signerKind!=='clinician'">Signing method<select v-model="signerUserId"><option value="">Together on this device</option><option v-for="r in record.recipients.filter(r=>r.kind===signerKind)" :key="r.id" :value="r.id">Share to {{ r.name }}’s portal</option></select></label><label v-if="signerUserId&&signerKind!=='clinician'&&['safety-plan','release-of-information','client-information-update','enrollment-document'].includes(documentKey)">Portal action<select v-model="portalAction"><option value="complete">Complete and sign this form</option><option v-if="documentKey!=='client-information-update'" value="sign">Review and sign the saved document</option></select></label><p v-if="signerUserId&&portalAction==='complete'" class="notice">Client completion creates a new version for staff review. Share that version again for any additional signatures.</p><label v-if="!signerUserId||signerKind==='clinician'">Signer’s name<input v-model="signerName" maxlength="200" required /></label><label v-if="signerKind==='guardian'" class="check"><input v-model="authorityConfirmed" type="checkbox" required />I verified this guardian is authorized to review and sign this document.</label><button :disabled="busy">{{ signerUserId&&signerKind!=='clinician'?(documentKey==='attendance-verification'?'Share copy to portal':portalAction==='complete'?'Share to portal to complete':'Share to portal for signature'):'Add signer' }}</button></form>
       <p v-if="record.clientId&&!record.recipients.length" class="notice">No portal accounts currently have permission to access this document. Configure the client’s portal relationship and clinical disclosure permission in their record, or sign together here.</p>
       <SafetyPlanSigning v-if="signing" :key="signing.id" :plan="record" :signer="signing" @cancel="signing=null" @signed="signatureSaved" />
      </section>
     </template>
    </template>
   </div>
  </div>
 </section>
</template>
<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {onBeforeRouteLeave,useRoute} from 'vue-router';
import liveApi from '../../services/api';
import {inject} from 'vue';
const api=inject('clinicalFormsHttp',liveApi);
import NoteAidClientPicker from '../clinical/NoteAidClientPicker.vue';
import SafetyPlanDocument from './SafetyPlanDocument.vue';
import ClinicalDocumentCopy from './ClinicalDocumentCopy.vue';
import SafetyPlanSigning from './SafetyPlanSigning.vue';
const props=defineProps({agencyId:[Number,String],initialRecordId:[Number,String],clientId:[Number,String],initialDocumentKey:{type:String,default:'safety-plan'},eventType:String,eventId:[Number,String],mine:Boolean,recordOnly:Boolean});
const route=useRoute();
const documentKey=ref(props.initialDocumentKey);
const crisisPath=computed(()=>`${route.params.organizationSlug?'/'+encodeURIComponent(route.params.organizationSlug):catalog.value?.branding?.slug?'/'+encodeURIComponent(catalog.value.branding.slug):''}/library?companyDocument=crisis-response-guide#crisis-response-guide-safety-planning`);
const portalAction=ref('sign'),sharingSection=ref(null);
function focusSharing(){sharingSection.value?.focus();sharingSection.value?.scrollIntoView({block:'start'});}
const readDocument=ref(null),formHeading=ref(null),formTypes=ref([]);
const formDescriptions={
 'cssrs-screener':'Record screening responses and follow-up.',
 'safety-plan':'Build a plan for coping, support and safety.',
 'release-of-information':'Choose what can be shared and with whom.',
 'client-information-update':'Update contact details and client information.',
 'attendance-verification':'Prepare a letter confirming an appointment.'
};
const catalog=ref(null),plans=ref([]),record=ref(null),editing=ref(false),form=ref({}),dirty=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const selectedClientId=ref(null),allowUnlinked=ref(false),overrideReason=ref(''),linkClientId=ref(null),confirmIdentity=ref(false),signing=ref(null),signerKind=ref('client'),signerName=ref(''),signerUserId=ref(''),authorityConfirmed=ref(false);
let generation=0,timer;
const savedSearch=ref('');
const filteredPlans=computed(()=>plans.value.filter(p=>(p.documentKey||'safety-plan')===documentKey.value&&`${p.name||''} ${p.title||''}`.toLowerCase().includes(savedSearch.value.trim().toLowerCase())));
const date=v=>new Date(v).toLocaleDateString();
const message=e=>e.response?.data?.error?.message||'Clinical documents could not be loaded. Please try again.';
function discard(){return !dirty.value||window.confirm('Leave without saving your document changes?');}
defineExpose({confirmDiscard:discard});
function reset(){catalog.value=null;plans.value=[];record.value=null;editing.value=false;dirty.value=false;form.value={};signing.value=null;allowUnlinked.value=false;selectedClientId.value=null;linkClientId.value=null;confirmIdentity.value=false;overrideReason.value='';error.value='';notice.value='';}
async function load({startNew=false}={}){const g=++generation;reset();loading.value=true;busy.value=false;if(props.recordOnly&&props.initialRecordId){await open(props.initialRecordId);if(record.value)catalog.value={template:record.value.template,branding:record.value.branding};loading.value=false;return;}try{const params={...(props.clientId?{clientId:props.clientId}:{agencyId:props.agencyId}),documentKey:documentKey.value,...(props.mine?{mine:'1'}:{}),...(props.eventId?{eventId:props.eventId,eventType:props.eventType}:{})};const [c,p]=await Promise.all([api.get('/clinical-forms/template',{params}),api.get('/clinical-forms',{params})]);if(g!==generation)return;catalog.value=c.data;formTypes.value=c.data.catalog||[];plans.value=p.data.plans;if(startNew||(props.eventId&&!props.initialRecordId))start();}catch(e){if(g===generation)error.value=message(e);}finally{if(g===generation)loading.value=false;}if(g===generation&&catalog.value&&props.initialRecordId&&!startNew)await open(props.initialRecordId);}
function start(){record.value=null;form.value={documentName:catalog.value.template.title,personLabel:catalog.value.client?.name||'',planDate:new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),reviewDate:'',supports:[{name:'',phone:'',role:''}],professionals:[{name:'988 Suicide & Crisis Lifeline',phone:'988',details:'Call or text for crisis support.'}],...(catalog.value.prefill||{})};selectedClientId.value=props.clientId||catalog.value.client?.id||null;allowUnlinked.value=false;overrideReason.value='';editing.value=true;dirty.value=true;signing.value=null;notice.value='';nextTick(()=>formHeading.value?.focus());}
async function open(id,version){if(!discard())return;const g=++generation;busy.value=true;error.value='';signing.value=null;try{const {data}=await api.get(`/clinical-forms/${id}`,{params:version?{version}:{}});if(g!==generation)return;if((props.agencyId&&Number(data.agencyId)!==Number(props.agencyId))||(props.clientId&&Number(data.clientId)!==Number(props.clientId)))throw new Error('Record context mismatch');record.value=data;portalAction.value=['client-information-update','enrollment-document'].includes(data.template.key)?'complete':'sign';documentKey.value=data.documentKey||data.template.key;editing.value=false;dirty.value=false;signerUserId.value='';signerName.value='';}catch(e){if(g===generation){record.value=null;error.value=message(e);}}finally{if(g===generation)busy.value=false;}}
async function startType(key){if(busy.value||loading.value||!discard())return;if(key===documentKey.value&&catalog.value?.template.key===key){start();return;}documentKey.value=key;await load({startNew:true});}
async function revokeAuthorization(){const reason=window.prompt('Record the client’s written revocation request. This stops future use of this authorization; it does not undo past disclosures.');if(!reason)return;await action(()=>api.post(`/clinical-forms/${record.value.id}/revoke-authorization`,{version:record.value.version,reason,confirm:true}),'Authorization revoked.');}
async function reviewUpdate(){if(!window.confirm('Confirm you reviewed this update and handled any necessary chart corrections separately.'))return;await action(()=>api.post(`/clinical-forms/${record.value.id}/review-update`,{version:record.value.version,reviewed:true}),'Review recorded.');}
function selectClient(c){if(!form.value.personLabel)form.value={...form.value,personLabel:c.full_name||c.fullName||c.name||c.initials||''};dirty.value=true;}
function edit(){if(record.value.version!==record.value.currentVersion){notice.value='Open the current version before editing.';return;}form.value=JSON.parse(JSON.stringify(record.value.data));editing.value=true;dirty.value=false;signing.value=null;}
function cancelEdit(){if(!discard())return;editing.value=false;dirty.value=false;}
async function action(fn,success){const g=generation;busy.value=true;error.value='';try{const {data}=await fn();if(g!==generation)return false;record.value=data;notice.value=success;return true;}catch(e){if(g===generation)error.value=message(e);return false;}finally{if(g===generation)busy.value=false;}}
async function save(){const payload={documentKey:documentKey.value,eventId:props.eventId,eventType:props.eventType,data:form.value,agencyId:props.agencyId,clientId:record.value?record.value.clientId:props.clientId||selectedClientId.value,version:record.value?.version,allowUnlinked:allowUnlinked.value,overrideReason:overrideReason.value};const id=record.value?.id;if(await action(()=>id?api.put(`/clinical-forms/${id}`,payload):api.post('/clinical-forms',payload),'Document saved.')){editing.value=false;dirty.value=false;portalAction.value=['client-information-update','enrollment-document'].includes(record.value.template.key)?'complete':'sign';const p=record.value;plans.value=[{id:p.id,clientId:p.clientId,version:p.version,documentName:p.data.documentName||'',name:p.data.personLabel,documentKey:p.template.key,title:p.template.title,screenStatus:p.data.screenStatus},...plans.value.filter(x=>x.id!==p.id)];}}
async function link(){if(await action(()=>api.post(`/clinical-forms/${record.value.id}/link`,{version:record.value.version,clientId:linkClientId.value,confirmIdentity:confirmIdentity.value}),'Linked to the client’s medical record.')){linkClientId.value=null;confirmIdentity.value=false;plans.value=plans.value.map(p=>p.id===record.value.id?{...p,clientId:record.value.clientId,version:record.value.version}:p);}}
async function addSigner(){if(await action(()=>api.post(`/clinical-forms/${record.value.id}/signers`,{version:record.value.version,kind:signerKind.value,name:signerName.value,userId:signerKind.value==='clinician'?null:signerUserId.value||null,authorityConfirmed:authorityConfirmed.value,allowCompletion:!!signerUserId.value&&signerKind.value!=='clinician'&&portalAction.value==='complete'&&['safety-plan','release-of-information','client-information-update','enrollment-document'].includes(documentKey.value),copyOnly:documentKey.value==='attendance-verification'&&signerKind.value!=='clinician'}),signerUserId.value&&signerKind.value!=='clinician'?'Shared to the portal. Email and enabled text notifications are grouped within a 30-minute window.':'Signer added to this version.')){signerName.value='';signerUserId.value='';authorityConfirmed.value=false;}}
async function revoke(s){await action(()=>api.post(`/clinical-forms/${record.value.id}/signers/${s.id}/revoke`,{version:record.value.version}),'Access withdrawn. Any previously recorded signature remains in the version history.');}
async function signatureSaved(){signing.value=null;await open(record.value.id);notice.value='Signature saved with this version.';}
async function refreshSignatures(){if(!record.value||editing.value||busy.value||document.hidden)return;const id=record.value.id,g=generation,version=record.value.version;try{const {data}=await api.get(`/clinical-forms/${id}`,{params:{version},skipGlobalLoading:true});if(g!==generation||editing.value||record.value?.id!==id)return;record.value={...record.value,signers:data.signers,currentVersion:data.currentVersion,history:data.history,revocation:data.revocation,reviewStatus:data.reviewStatus};if(data.currentVersion!==version)signing.value=null;}catch(e){if(g===generation&&[401,403,404].includes(e.response?.status)){record.value=null;signing.value=null;error.value=message(e);}}}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue='';}}
watch(signerKind,()=>{signerUserId.value='';authorityConfirmed.value=false;});watch(()=>[props.agencyId,props.clientId,props.eventId,props.mine,props.initialRecordId],()=>{formTypes.value=[];load();},{immediate:true});
onBeforeRouteLeave(()=>discard());onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);timer=setInterval(refreshSignatures,15000);});onBeforeUnmount(()=>{++generation;clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);reset();});
</script>
<style scoped>
.workspace-brand{display:inline-flex;align-items:center;gap:8px;font-size:14px;font-weight:650;white-space:nowrap}.workspace-brand img{width:30px;height:30px}.workspace-agency{font-size:13px;color:#597167}.needs-client-link{display:inline-flex;justify-self:start;font-size:11px;font-weight:650;background:#fff3d6;color:#79520c;border:1px solid #ead7a4;border-radius:5px;padding:4px 7px;}
.safety-workspace{margin:24px 0;color:#233c35}.workspace-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px;border:1px solid #d8e5dc;background:#f2f6f0;border-radius:14px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:11px}h2{margin:8px 0}.workspace-heading p{line-height:1.7}.plan-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:24px;margin-top:24px}aside h3{font-size:15px}aside button{display:grid;width:100%;text-align:left;gap:6px;margin:8px 0}aside span{font-size:11px}.plan-layout.record-only{grid-template-columns:minmax(0,1fr)}.plan-content{min-width:0}button,select{font:inherit;padding:11px 14px;border:1px solid #acbeb2;border-radius:7px;background:white;color:#175b48;cursor:pointer}button:disabled{opacity:.5;cursor:default}.actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:18px 0}.actions label{margin:0}.actions span{font-size:12px}label{display:grid;gap:8px;font-size:13px;margin:14px 0}input:not([type=checkbox]),textarea{font:inherit;padding:11px;border:1px solid #acbeb2;border-radius:6px;width:100%;box-sizing:border-box}.check{display:flex;align-items:flex-start;line-height:1.6}.notice{padding:16px;background:#f5f1e5;line-height:1.7;font-size:13px}.plan-linkage,.signers{padding:22px;margin:20px 0;border:1px solid #d6e2d9;border-radius:10px}.plan-linkage summary{cursor:pointer}.signers>p{line-height:1.7}.signer-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px;border-top:1px solid #d8e5dc;padding:14px 0;font-size:13px}.signer-setup{padding:18px;background:#f5f8f4;border-radius:8px}[role=alert]{color:#922d23;padding:14px;background:#fff0ec}[role=status]{padding:12px;background:#edf6e9}@media(max-width:950px){.plan-layout{grid-template-columns:1fr}.workspace-heading{align-items:flex-start;flex-direction:column}}
.template-picker{margin:24px 0}.picker-heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:14px}.picker-heading h3{margin:0;font-size:17px}.picker-heading>span{font-size:13px;color:#597167}
.form-types{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}
.template-card{display:flex;flex-direction:column;align-items:stretch;text-align:left;padding:18px;border:1px solid #d6e2d9;border-radius:12px;background:#fff;box-shadow:0 2px 6px #183b2f05;transition:border-color .18s,box-shadow .18s;min-width:0}
.template-card:hover:not(:disabled),.template-card--active{border-color:#175b48;box-shadow:0 3px 12px #183b2f14}.template-card:focus-visible{outline:3px solid #175b48;outline-offset:3px}
.document-preview{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:5px;width:64px;height:82px;box-sizing:border-box;padding:10px;margin-bottom:16px;border:1px solid #c6d7cc;border-radius:4px 12px 4px 4px;background:linear-gradient(135deg,#f1f6ef,#fff);box-shadow:3px 3px 0 #edf3ee;color:#175b48}.document-preview svg{width:19px;height:22px;flex-shrink:0}.preview-rule{height:2px;width:100%;background:#d7e2d9}.preview-rule--heading{width:65%;background:#7da48a}.preview-field{height:6px;width:100%;border:1px solid #dde7df;border-radius:1px}.preview-plus{position:absolute;right:-8px;bottom:-5px;display:grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#175b48;color:#fff;font-size:18px;border:2px solid white}
